@import "tailwindcss";

@theme {
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-display: var(--font-space-grotesk), var(--font-inter), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jetbrains-mono), ui-monospace, SFMono-Regular, monospace;

  --color-navy-950: #060914;
  --color-navy-900: #0a0e27;
  --color-navy-800: #121735;
  --color-navy-700: #1a2150;
  --color-navy-600: #28306a;

  --color-electric-700: #1747cc;
  --color-electric-600: #1f5cff;
  --color-electric-500: #2d6bff;
  --color-electric-400: #4f8bff;
  --color-electric-300: #84acff;

  --color-iris: #7c5cff;
  --color-aqua: #22d3ee;

  --color-ink: #0b1220;
  --color-mist: #f6f8fc;
  --color-line: #e4e9f2;

  --shadow-glow: 0 18px 60px -22px rgba(45, 107, 255, 0.55);
  --shadow-card: 0 1px 2px rgba(11, 18, 32, 0.04), 0 14px 38px -16px rgba(11, 18, 32, 0.14);
  --shadow-lift: 0 2px 4px rgba(11, 18, 32, 0.05), 0 26px 60px -24px rgba(11, 18, 32, 0.22);

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}

@layer base {
  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
  }
  body {
    background-color: #ffffff;
    color: var(--color-ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    overflow-x: hidden;
  }
  h1, h2, h3, h4 {
    font-family: var(--font-display);
    letter-spacing: -0.025em;
    line-height: 1.05;
  }
  ::selection {
    background: rgba(45, 107, 255, 0.24);
    color: var(--color-navy-950);
  }
  :focus-visible {
    outline: 2px solid var(--color-electric-500);
    outline-offset: 3px;
    border-radius: 4px;
  }
}

.text-gradient {
  background-image: linear-gradient(112deg, var(--color-electric-400) 0%, var(--color-iris) 48%, var(--color-aqua) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.text-gradient-light {
  background-image: linear-gradient(110deg, #ffffff 0%, #d4e0ff 55%, #8fb4ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.bg-grid-dark {
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.045) 1px, transparent 1px);
  background-size: 64px 64px;
}
.bg-grid-light {
  background-image:
    linear-gradient(rgba(11, 18, 32, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(11, 18, 32, 0.05) 1px, transparent 1px);
  background-size: 64px 64px;
}
.bg-dots {
  background-image: radial-gradient(rgba(255, 255, 255, 0.10) 1px, transparent 1px);
  background-size: 22px 22px;
}
.mask-fade-edges {
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);
}
.mask-fade-b {
  -webkit-mask-image: linear-gradient(180deg, #000 60%, transparent);
  mask-image: linear-gradient(180deg, #000 60%, transparent);
}

.glass-dark {
  background: rgba(18, 23, 53, 0.55);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.09);
}
.glass-light {
  background: rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(11, 18, 32, 0.06);
}

.ring-gradient {
  position: relative;
  isolation: isolate;
}
.ring-gradient::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(130deg, rgba(79, 139, 255, 0.7), rgba(124, 92, 255, 0.35) 45%, rgba(34, 211, 238, 0.55));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
.animate-marquee { animation: marquee 38s linear infinite; }
.animate-marquee-slow { animation: marquee 64s linear infinite; }

@keyframes floaty {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-16px); }
}
.animate-floaty { animation: floaty 9s ease-in-out infinite; }

@keyframes pulse-glow {
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 0.85; transform: scale(1.07); }
}
.animate-pulse-glow { animation: pulse-glow 9s ease-in-out infinite; }

@keyframes spin-slow {
  to { transform: rotate(360deg); }
}
.animate-spin-slow { animation: spin-slow 26s linear infinite; }

::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(100, 116, 139, 0.38);
  border-radius: 999px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-thumb:hover { background: rgba(100, 116, 139, 0.6); background-clip: padding-box; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  .animate-marquee, .animate-marquee-slow, .animate-floaty, .animate-pulse-glow, .animate-spin-slow {
    animation: none !important;
  }
}

