@import "tailwindcss";

@theme {
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-display: var(--font-space-grotesk), var(--font-inter), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jetbrains-mono), ui-monospace, SFMono-Regular, monospace;

  /* Stripe-inspired core */
  --color-ink: #0a2540;        /* headings — Stripe navy */
  --color-slate: #425466;      /* body text */
  --color-mist: #f6f9fc;       /* light section bg (cloud) */
  --color-cloud: #eef3f9;      /* slightly deeper light */
  --color-line: #e3e8ee;       /* borders */

  --color-blurple-300: #b7b2ff;
  --color-blurple-400: #8a83ff;
  --color-blurple-500: #635bff; /* brand primary */
  --color-blurple-600: #5249f0;
  --color-blurple-700: #4239d6;

  --color-sky-400: #00d4ff;
  --color-sky-500: #0bb5ff;
  --color-mintx-400: #3ecf8e;
  --color-mintx-500: #23c386;
  --color-coral-400: #ff7eb6;
  --color-coral-500: #ff5996;
  --color-peach-400: #ffd79d;

  /* legacy aliases kept for continuity */
  --color-navy-950: #061022;
  --color-navy-900: #0a2540;
  --color-navy-800: #102a43;
  --color-navy-700: #1c3a5e;
  --color-navy-600: #2a4a73;
  --color-electric-700: #4239d6;
  --color-electric-600: #5249f0;
  --color-electric-500: #635bff;
  --color-electric-400: #8a83ff;
  --color-electric-300: #b7b2ff;
  --color-iris: #7c5cff;
  --color-aqua: #00d4ff;

  /* Stripe-style soft layered shadows */
  --shadow-soft: 0 2px 5px -1px rgba(50, 50, 93, 0.12), 0 1px 3px -1px rgba(10, 37, 64, 0.12);
  --shadow-card: 0 13px 27px -8px rgba(50, 50, 93, 0.18), 0 8px 16px -10px rgba(10, 37, 64, 0.12);
  --shadow-lift: 0 24px 48px -14px rgba(50, 50, 93, 0.22), 0 12px 24px -16px rgba(10, 37, 64, 0.14);
  --shadow-xl: 0 50px 100px -28px rgba(50, 50, 93, 0.3), 0 30px 60px -32px rgba(10, 37, 64, 0.2);
  --shadow-glow: 0 16px 40px -12px rgba(99, 91, 255, 0.5);

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}

@layer base {
  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
  }
  body {
    background-color: #ffffff;
    color: var(--color-slate);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    overflow-x: hidden;
  }
  h1, h2, h3, h4 {
    font-family: var(--font-display);
    color: var(--color-ink);
    letter-spacing: -0.025em;
    line-height: 1.05;
  }
  ::selection {
    background: rgba(99, 91, 255, 0.22);
    color: var(--color-ink);
  }
  :focus-visible {
    outline: 2px solid var(--color-blurple-500);
    outline-offset: 3px;
    border-radius: 4px;
  }
}

/* ---- Gradient text ---- */
.text-gradient {
  background-image: linear-gradient(100deg, #635bff 0%, #2d8dff 48%, #00d4ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.text-gradient-warm {
  background-image: linear-gradient(100deg, #635bff 0%, #ff5996 60%, #ffb15c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.text-gradient-light {
  background-image: linear-gradient(100deg, #ffffff 0%, #d7e6ff 55%, #9fd4ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* ---- Backgrounds & textures ---- */
.bg-grid-light {
  background-image:
    linear-gradient(rgba(10, 37, 64, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(10, 37, 64, 0.05) 1px, transparent 1px);
  background-size: 56px 56px;
}
.bg-grid-dark {
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
  background-size: 56px 56px;
}
.bg-dots {
