          <div className="mx-auto mt-10 grid max-w-4xl grid-cols-1 gap-8 sm:grid-cols-3">
            {study.results.map((r) => (
              <div key={r.label} className="text-center">
                <p className="text-gradient font-display text-5xl font-bold tracking-tight sm:text-6xl">
                  {r.value}
                </p>
                <p className="mt-3 text-sm text-white/55">{r.label}</p>
              </div>
            ))}
          </div>

          <figure className="mx-auto mt-16 max-w-3xl text-center">
            <Quote className="mx-auto h-10 w-10 text-electric-400/30" aria-hidden />
            <blockquote className="mt-4 text-balance font-display text-2xl font-medium leading-snug text-white">
              &ldquo;{study.quote.text}&rdquo;
            </blockquote>
            <figcaption className="mt-6 text-sm text-white/55">
              <span className="font-semibold text-white">{study.quote.author}</span>
              {" — "}
              {study.quote.role}
            </figcaption>
          </figure>
        </Container>
      </Section>

      <Section tone="mist">
        <Container>
          <h2 className="font-display text-2xl font-semibold text-ink sm:text-3xl">
            More work
          </h2>
          <div className="mt-10 grid gap-5 md:grid-cols-2">
            {others.map((c) => (
              <CaseStudyCard key={c.slug} study={c} variant="light" />
            ))}
          </div>
        </Container>
      </Section>

      <CTASection />
    </>
  );
}

