"use client";

import { useMemo, useState } from "react";
import { SearchX } from "lucide-react";
import { ProductCard } from "@/components/cards/ProductCard";
import { ComingSoonCard } from "@/components/cards/ComingSoonCard";
import {
  ProductFilters,
  type ProductFilterState,
} from "@/components/product/ProductFilters";
import type { Product } from "@/content/types";

type ProductGridProps = {
  products: Product[];
};

const INITIAL_STATE: ProductFilterState = {
  search: "",
  category: null,
  industrySlug: null,
  featuredOnly: false,
};

/**
 * Owns the filter state and renders the filtered product grid. The
 * ComingSoonCard is always appended so the grid never reads as empty, and a
 * graceful empty state replaces the product cards when filters exclude
 * everything (the ecosystem tile still anchors the section).
 */
export function ProductGrid({ products }: ProductGridProps) {
  const [filters, setFilters] = useState<ProductFilterState>(INITIAL_STATE);

  const handleChange = (next: Partial<ProductFilterState>) => {
    setFilters((prev) => ({ ...prev, ...next }));
  };

  const filtered = useMemo(() => {
    const query = filters.search.trim().toLowerCase();

    return products.filter((product) => {
      if (filters.featuredOnly && !product.featured) return false;
      if (filters.category && product.category !== filters.category) return false;
      if (filters.industrySlug && !product.industries.includes(filters.industrySlug)) {
        return false;
      }

      if (query) {
        const haystack = [
          product.name,
          product.tagline,
          product.shortDescription,
        ]
          .join(" ")
          .toLowerCase();
        if (!haystack.includes(query)) return false;
      }

      return true;
    });
  }, [products, filters]);

  const isEmpty = filtered.length === 0;

  return (
    <div>
      <ProductFilters
        search={filters.search}
        category={filters.category}
        industrySlug={filters.industrySlug}
        featuredOnly={filters.featuredOnly}
        resultCount={filtered.length}
        results={filtered}
        onChange={handleChange}
      />

      {isEmpty && (
        <div className="mt-10 flex flex-col items-center justify-center rounded-3xl bg-white/60 px-6 py-12 text-center ring-1 ring-[#0B57D0]/8">
          <span className="inline-flex h-14 w-14 items-center justify-center rounded-2xl bg-gradient-to-br from-[#0B57D0]/10 to-[#00C2FF]/10 text-[#0B57D0] ring-1 ring-[#0B57D0]/8">
            <SearchX size={24} strokeWidth={2.1} aria-hidden />
          </span>
          <h3 className="mt-5 text-[18px] font-bold text-[#061224]">
            No products match those filters
          </h3>
          <p className="mt-2 max-w-md text-[14px] leading-[1.65] text-[#0B1B33]/60">
            Try clearing a filter or adjusting your search. The ecosystem is
            growing — new products join the catalog regularly.
          </p>
          <button
            type="button"
            onClick={() => setFilters(INITIAL_STATE)}
            className="mt-6 inline-flex items-center gap-1.5 rounded-full bg-gradient-to-br from-[#0B57D0] to-[#00C2FF] px-5 py-2.5 text-[13.5px] font-semibold text-white shadow-[0_10px_30px_-8px_rgba(11,87,208,0.55)] transition-all duration-300 hover:-translate-y-0.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0B57D0]/40 focus-visible:ring-offset-2"
          >
            Reset filters
          </button>
        </div>
      )}

      <div className="mt-10 grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {filtered.map((product) => (
          <ProductCard key={product.slug} product={product} />
        ))}
        <ComingSoonCard />
      </div>
    </div>
  );
}

