352	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform duration-300 ${
353	              featuredOnly ? "translate-x-6" : "translate-x-1"
354	            }`}
355	          />
356	        </button>
357	      </div>
358	    </div>
359	  );
360	}
