"use client";

import { useEffect, useState, type KeyboardEvent } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Search, X, Sparkles, ArrowRight } from "lucide-react";
import { Icon } from "@/components/ui/Icon";
import { allCategories } from "@/content/products";
import { industries } from "@/content/industries";
import type { Product } from "@/content/types";

/**
 * The shape of the filter state. The parent (ProductGrid) owns this state and
 * passes it down; this component is fully controlled and reports every change
 * back through `onChange`.
 */
export type ProductFilterState = {
  search: string;
  /** Selected product category, or null for "all categories". */
  category: string | null;
  /** Selected industry slug, or null for "all industries". */
  industrySlug: string | null;
  /** Show only featured products. */
  featuredOnly: boolean;
};

type ProductFiltersProps = {
  search: string;
  category: string | null;
  industrySlug: string | null;
  featuredOnly: boolean;
  /** Number of products matching the current filters (excludes the ecosystem tile). */
  resultCount: number;
  /** Products matching the current filters — used to render the instant-results dropdown. */
  results: Product[];
  onChange: (next: Partial<ProductFilterState>) => void;
};

/** How many matches the instant-results dropdown shows before "and N more". */
const MAX_SEARCH_RESULTS = 6;

const chipBase =
  "inline-flex items-center gap-2 rounded-full px-4 py-2 text-[13px] font-semibold transition-all duration-300 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0B57D0]/40 focus-visible:ring-offset-2 focus-visible:ring-offset-[#F5F8FC]";

const chipSelected =
  "bg-gradient-to-br from-[#0B57D0] to-[#00C2FF] text-white shadow-[0_8px_20px_-8px_rgba(11,87,208,0.55)]";

const chipUnselected =
  "bg-white text-[#0B1B33]/70 ring-1 ring-[#0B57D0]/12 hover:ring-[#0B57D0]/30 hover:text-[#0B57D0]";

/**
 * Search + category chips + industry chips + a "featured only" toggle.
 * Selected chips are brand-gradient filled; unselected are white ring chips.
 * A live results count sits beside the search field.
 */
export function ProductFilters({
  search,
  category,
  industrySlug,
  featuredOnly,
  resultCount,
  results,
  onChange,
}: ProductFiltersProps) {
  const categories = allCategories();
  const hasActiveFilters =
    search.trim() !== "" || category !== null || industrySlug !== null || featuredOnly;

  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);

  const query = search.trim();
  const visibleResults = results.slice(0, MAX_SEARCH_RESULTS);
  const showResults = open && query !== "";

  // Reset the keyboard highlight whenever the query or the result set changes.
  useEffect(() => {
    setActiveIndex(-1);
  }, [search, resultCount]);

  const goToProduct = (slug: string) => {
    setOpen(false);
    setActiveIndex(-1);
    router.push(`/products/${slug}`);
  };

  const handleSearchKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Escape") {
      setOpen(false);
      return;
    }
    if (query === "" || visibleResults.length === 0) return;
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setOpen(true);
      setActiveIndex((i) => (i + 1) % visibleResults.length);
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setOpen(true);
      setActiveIndex((i) => (i <= 0 ? visibleResults.length - 1 : i - 1));
    } else if (
      e.key === "Enter" &&
      activeIndex >= 0 &&
      activeIndex < visibleResults.length
    ) {
      e.preventDefault();
      goToProduct(visibleResults[activeIndex].slug);
    }
  };

  return (
    <div className="relative z-20 rounded-4xl bg-white/70 p-6 ring-1 ring-[#0B57D0]/8 shadow-soft backdrop-blur-sm lg:p-8">
      {/* Search row */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative w-full sm:max-w-md">
          <label className="relative block">
            <span className="sr-only">Search products</span>
            <Search
              size={18}
              strokeWidth={2.2}
              aria-hidden
              className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-[#0B57D0]/50"
            />
            <input
              type="search"
              value={search}
              onChange={(e) => {
                onChange({ search: e.target.value });
                setOpen(true);
              }}
              onFocus={() => setOpen(true)}
              onBlur={() => setTimeout(() => setOpen(false), 120)}
              onKeyDown={handleSearchKeyDown}
              role="combobox"
              aria-expanded={showResults}
              aria-controls="product-search-results"
              aria-autocomplete="list"
              aria-activedescendant={
                activeIndex >= 0 ? `product-search-option-${activeIndex}` : undefined
              }
              placeholder="Search products, capabilities…"
              className="w-full rounded-full border-0 bg-[#F5F8FC] py-3 pl-11 pr-4 text-[14px] text-[#0B1B33] ring-1 ring-[#0B57D0]/10 transition-all duration-300 placeholder:text-[#0B1B33]/40 focus:outline-none focus:ring-2 focus:ring-[#0B57D0]/35"
            />
          </label>

          {/* Instant-results dropdown — surfaces matches right under the field so
              users see results without scrolling past the filters below. It floats
              over the layout (absolute), so the existing design is left intact. */}
          {showResults && (
            <div
              id="product-search-results"
              role="listbox"
              aria-label="Product search results"
              className="absolute left-0 right-0 top-full z-50 mt-2 overflow-hidden rounded-3xl bg-white p-2 text-left ring-1 ring-[#0B57D0]/12 shadow-elevated"
            >
              {visibleResults.length > 0 ? (
                <>
                  <ul className="max-h-[60vh] space-y-1 overflow-auto">
                    {visibleResults.map((product, i) => {
                      const active = i === activeIndex;
                      const accentStyle = product.accent
                        ? {
                            backgroundImage: `linear-gradient(to bottom right, ${product.accent.from}, ${product.accent.to})`,
                          }
                        : undefined;
                      return (
                        <li key={product.slug}>
                          <Link
                            id={`product-search-option-${i}`}
                            role="option"
                            aria-selected={active}
                            href={`/products/${product.slug}`}
                            onMouseDown={(e) => e.preventDefault()}
                            onMouseEnter={() => setActiveIndex(i)}
                            onClick={() => {
                              setOpen(false);
                              setActiveIndex(-1);
                            }}
                            className={`flex items-center gap-3 rounded-2xl px-3 py-2.5 transition-colors duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0B57D0]/40 ${
                              active ? "bg-[#0B57D0]/8" : "hover:bg-[#F5F8FC]"
                            }`}
                          >
                            <span
                              className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-[#0B57D0] to-[#00C2FF] text-white"
                              style={accentStyle}
                            >
                              <Icon name={product.icon} size={16} strokeWidth={2.3} />
                            </span>
                            <span className="min-w-0 flex-1">
                              <span className="flex items-center gap-2">
                                <span className="truncate text-[14px] font-semibold text-[#061224]">
                                  {product.name}
                                </span>
                                <span className="hidden shrink-0 rounded-full bg-[#0B57D0]/6 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-[0.12em] text-[#0B57D0]/80 sm:inline-block">
                                  {product.category}
                                </span>
                              </span>
                              <span className="mt-0.5 block truncate text-[12.5px] text-[#0B1B33]/55">
                                {product.tagline}
                              </span>
                            </span>
                            <ArrowRight
                              size={15}
                              strokeWidth={2.3}
                              aria-hidden
                              className="shrink-0 text-[#0B57D0]/50"
                            />
                          </Link>
                        </li>
                      );
                    })}
                  </ul>
                  {resultCount > visibleResults.length && (
                    <p className="px-3 pb-1 pt-2 text-center text-[12px] font-medium text-[#0B1B33]/50">
                      Showing top {visibleResults.length} of {resultCount} — keep typing to
                      narrow it down
                    </p>
                  )}
                </>
              ) : (
                <div className="px-4 py-6 text-center">
                  <p className="text-[13.5px] font-semibold text-[#061224]">
                    No products match &ldquo;{query}&rdquo;
                  </p>
                  <p className="mt-1 text-[12.5px] text-[#0B1B33]/55">
                    Try a different term or clear your filters.
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-3">
          <p className="text-[13px] font-medium text-[#0B1B33]/60" aria-live="polite">
            <span className="font-bold text-[#0B57D0]">{resultCount}</span>{" "}
            {resultCount === 1 ? "product" : "products"}
          </p>
          {hasActiveFilters && (
            <button
              type="button"
              onClick={() =>
                onChange({
                  search: "",
                  category: null,
                  industrySlug: null,
                  featuredOnly: false,
                })
              }
              className="inline-flex items-center gap-1.5 rounded-full bg-[#0B57D0]/6 px-3 py-1.5 text-[12px] font-semibold text-[#0B57D0] transition-colors hover:bg-[#0B57D0]/12 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0B57D0]/40"
            >
              <X size={13} strokeWidth={2.6} aria-hidden />
              Clear all
            </button>
          )}
        </div>
      </div>

      {/* Category chips */}
      <fieldset className="mt-7">
        <legend className="mb-3 text-[11px] font-semibold uppercase tracking-[0.16em] text-[#0B1B33]/45">
          Category
        </legend>
        <div className="flex flex-wrap gap-2.5">
          <button
            type="button"
            aria-pressed={category === null}
            onClick={() => onChange({ category: null })}
            className={`${chipBase} ${category === null ? chipSelected : chipUnselected}`}
          >
            All categories
          </button>
          {categories.map((cat) => {
            const selected = category === cat;
            return (
              <button
                key={cat}
                type="button"
                aria-pressed={selected}
                onClick={() => onChange({ category: selected ? null : cat })}
                className={`${chipBase} ${selected ? chipSelected : chipUnselected}`}
              >
                {cat}
              </button>
            );
          })}
        </div>
      </fieldset>

      {/* Industry chips */}
      <fieldset className="mt-7">
        <legend className="mb-3 text-[11px] font-semibold uppercase tracking-[0.16em] text-[#0B1B33]/45">
          Industry
        </legend>
        <div className="flex flex-wrap gap-2.5">
          <button
            type="button"
            aria-pressed={industrySlug === null}
            onClick={() => onChange({ industrySlug: null })}
            className={`${chipBase} ${industrySlug === null ? chipSelected : chipUnselected}`}
          >
            All industries
          </button>
          {industries.map((ind) => {
            const selected = industrySlug === ind.slug;
            return (
              <button
                key={ind.slug}
                type="button"
                aria-pressed={selected}
                onClick={() => onChange({ industrySlug: selected ? null : ind.slug })}
                className={`${chipBase} ${selected ? chipSelected : chipUnselected}`}
              >
                <Icon
                  name={ind.icon}
                  size={14}
                  strokeWidth={2.3}
                  className={selected ? "text-white" : "text-[#0B57D0]/70"}
                />
                {ind.name}
              </button>
            );
          })}
        </div>
      </fieldset>

      {/* Featured toggle */}
      <div className="mt-7 flex items-center justify-between border-t border-[#0B57D0]/8 pt-6">
        <div className="flex items-center gap-2.5">
          <span className="inline-flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-[#0B57D0]/10 to-[#00C2FF]/10 text-[#0B57D0] ring-1 ring-[#0B57D0]/8">
            <Sparkles size={16} strokeWidth={2.3} aria-hidden />
          </span>
          <div>
            <p className="text-[13.5px] font-semibold text-[#061224]">Featured only</p>
            <p className="text-[12px] text-[#0B1B33]/55">Highlighted, flagship products</p>
          </div>
        </div>
        <button
          type="button"
          role="switch"
          aria-checked={featuredOnly}
          aria-label="Show featured products only"
          onClick={() => onChange({ featuredOnly: !featuredOnly })}
          className={`relative inline-flex h-7 w-12 shrink-0 items-center rounded-full transition-colors duration-300 focus:outline-none focus-visible:ring-2 focus-visible:ring-[#0B57D0]/40 focus-visible:ring-offset-2 ${
            featuredOnly
              ? "bg-gradient-to-br from-[#0B57D0] to-[#00C2FF]"
              : "bg-[#0B1B33]/15"
          }`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform duration-300 ${
              featuredOnly ? "translate-x-6" : "translate-x-1"
            }`}
          />
        </button>
      </div>
    </div>
  );
}

