import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { Icon } from "@/components/ui/Icon";
import type { Product } from "@/content/types";

type ProductCardProps = {
  product: Product;
};

/**
 * Premium product card — white surface, ring + shadow-soft, card-hover lift.
 * The whole card is a link to the product detail page. Uses the product's
 * accent gradient when provided, otherwise the brand gradient.
 */
export function ProductCard({ product }: ProductCardProps) {
  const accentStyle = product.accent
    ? {
        backgroundImage: `linear-gradient(to bottom right, ${product.accent.from}, ${product.accent.to})`,
      }
    : undefined;

  const isLive = product.status === "live";

  return (
    <Link
      href={`/products/${product.slug}`}
      className="group card-hover relative flex h-full flex-col overflow-hidden rounded-3xl bg-white p-7 ring-1 ring-[#0B57D0]/8 shadow-soft transition-all duration-500 hover:shadow-elevated hover:ring-[#0B57D0]/20"
    >
      <div className="absolute top-0 right-0 h-32 w-32 rounded-full bg-gradient-to-br from-[#0B57D0]/8 to-[#00C2FF]/8 blur-2xl" />

      {/* Header: icon tile + status badge */}
      <div className="relative flex items-start justify-between gap-3">
        <span
          className="inline-flex h-11 w-11 items-center justify-center rounded-2xl bg-gradient-to-br from-[#0B57D0] to-[#00C2FF] text-white shadow-[0_6px_16px_-4px_rgba(11,87,208,0.5)]"
          style={accentStyle}
        >
          <Icon name={product.icon} size={20} strokeWidth={2.2} />
        </span>

        {isLive && (
          <span className="inline-flex items-center gap-1.5 rounded-full bg-[#16A34A]/10 px-2.5 py-1 text-[10.5px] font-semibold uppercase tracking-[0.14em] text-[#16A34A]">
            <span className="relative flex h-1.5 w-1.5">
              <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-[#16A34A] opacity-75" />
              <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-[#16A34A]" />
            </span>
            Live
          </span>
        )}
      </div>

      {/* Category eyebrow */}
      <span className="relative mt-6 inline-flex w-fit items-center rounded-full bg-[#0B57D0]/6 px-2.5 py-1 text-[10.5px] font-semibold uppercase tracking-[0.15em] text-[#0B57D0]/85">
        {product.category}
      </span>

      {/* Name + description */}
      <h3 className="relative mt-3 text-[19px] font-bold leading-tight text-[#061224] lg:text-[20px]">
        {product.name}
      </h3>
      <p className="relative mt-2.5 text-[14px] leading-[1.65] text-[#0B1B33]/65">
        {product.shortDescription}
      </p>

      {/* Key benefits */}
      {product.keyBenefits.length > 0 && (
        <ul className="relative mt-5 space-y-2.5">
          {product.keyBenefits.slice(0, 3).map((benefit) => (
            <li
              key={benefit.title}
              className="flex items-center gap-2.5 text-[13.5px] font-medium text-[#0B1B33]/75"
            >
              <span className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br from-[#0B57D0]/10 to-[#00C2FF]/10 text-[#0B57D0] ring-1 ring-[#0B57D0]/8">
                <Icon name={benefit.icon} size={13} strokeWidth={2.3} />
              </span>
              {benefit.title}
            </li>
          ))}
        </ul>
      )}

      {/* Learn more affordance */}
      <div className="relative mt-auto pt-6">
        <span className="inline-flex items-center gap-1.5 text-[13.5px] font-semibold text-[#0B57D0]">
          Learn more
          <ArrowRight
            size={15}
            strokeWidth={2.4}
            className="transition-transform duration-300 group-hover:translate-x-1"
          />
        </span>
      </div>
    </Link>
  );
}

