import type { Metadata } from "next";
import { notFound } from "next/navigation";

import { getProduct, allProductSlugs } from "@/content/products";
import { company } from "@/content/company";
import { customDetailComponents } from "@/components/product/customDetail";
import { ProductDetailTemplate } from "@/components/product/ProductDetailTemplate";
import { ProductSchema, BreadcrumbSchema } from "@/components/seo/JsonLd";
import { SiteHeader } from "@/components/site/SiteHeader";
import { SiteFooter } from "@/components/site/SiteFooter";
import { Breadcrumbs } from "@/components/site/Breadcrumbs";

type PageParams = { slug: string };

/**
 * Pre-render every product detail page at build time. Adding a product to the
 * registry automatically produces its static route — no routing changes.
 */
export async function generateStaticParams(): Promise<PageParams[]> {
  return allProductSlugs().map((slug) => ({ slug }));
}

/**
 * Per-product SEO metadata, assembled from the product's `seo` block. Falls
 * back to a sensible default title when the slug doesn't resolve to a product.
 */
export async function generateMetadata({
  params,
}: {
  params: PageParams;
}): Promise<Metadata> {
  const product = getProduct(params.slug);

  if (!product) {
    return {
      title: `Products | ${company.name}`,
    };
  }

  const { title, description, keywords } = product.seo;

  return {
    title,
    description,
    keywords,
    openGraph: {
      title,
      description,
      type: "website",
    },
  };
}

/**
 * Dynamic product detail route. Bespoke products render their own hand-built
 * component (which owns its header/footer); every other product renders the
 * data-driven template wrapped in the shared site chrome and structured data.
 */
export default async function Page({ params }: { params: PageParams }) {
  const product = getProduct(params.slug);

  if (!product) notFound();

  if (product.customDetailComponent) {
    const Custom = customDetailComponents[product.customDetailComponent];
    if (!Custom) notFound();
    return <Custom />;
  }

  return (
    <>
      <SiteHeader />
      <ProductSchema product={product} />
      <BreadcrumbSchema
        items={[
          { name: "Home", url: company.url },
          { name: "Products", url: `${company.url}/products` },
          {
            name: product.name,
            url: `${company.url}/products/${product.slug}`,
          },
        ]}
      />
      <div className="mx-auto max-w-[1280px] px-6 pt-28 lg:px-8">
        <Breadcrumbs
          items={[
            { label: "Products", href: "/products" },
            { label: product.name },
          ]}
        />
      </div>
      <ProductDetailTemplate product={product} />
      <SiteFooter />
    </>
  );
}

/**
 * Site navigation, kept as data so the header and footer never need editing
 * when content scales. Footer "Products"/"Industries" columns are generated
 * from the registries at render time (see SiteFooter), so they always stay
 * in sync — these static columns cover everything else.
 */

export type NavLink = { label: string; href: string };

export const primaryNav: NavLink[] = [
  { label: "Products", href: "/products" },
  { label: "Industries", href: "/industries" },
  { label: "Why Us", href: "/#why-us" },
  { label: "Contact", href: "/contact" },
];

export const footerColumns: { title: string; links: NavLink[] }[] = [
  {
    title: "Platform",
    links: [
      { label: "All Products", href: "/products" },
      { label: "Industries", href: "/industries" },
      { label: "Why Choose Us", href: "/#why-us" },
      { label: "Success Stories", href: "/#testimonials" },
    ],
  },
  {
    title: "Company",
    links: [
      { label: "About iWebWiser", href: "https://iwebwiser.com/our-company" },
      { label: "Case Studies", href: "https://iwebwiser.com" },
      { label: "Careers", href: "https://iwebwiser.com" },
      { label: "Contact Sales", href: "/contact" },
    ],
  },
  {
    title: "Get Started",
    links: [
      { label: "Request a Demo", href: "/contact?intent=demo" },
      { label: "Talk to Sales", href: "/contact?intent=sales" },
      { label: "Schedule a Consultation", href: "/contact?intent=consultation" },
    ],
  },
];

export const legalNav: NavLink[] = [
  { label: "Privacy", href: "https://iwebwiser.com" },
  { label: "Terms", href: "https://iwebwiser.com" },
  { label: "Security", href: "/contact" },
];

