4	
5	type Variant =
6	  | "primary"
7	  | "gradient"
8	  | "light"
9	  | "outlineLight"
10	  | "outlineDark"
11	  | "ghost";
12	type Size = "md" | "lg";
13	
14	const base =
15	  "group inline-flex items-center justify-center gap-2 rounded-full font-medium tracking-tight transition-all duration-300 ease-out focus-visible:outline-none disabled:cursor-not-allowed disabled:opacity-50 whitespace-nowrap";
16	
17	const sizes: Record<Size, string> = {
18	  md: "px-5 py-2.5 text-sm",
19	  lg: "px-7 py-3.5 text-[15px]",
20	};
21	
22	const variants: Record<Variant, string> = {
23	  primary:
24	    "bg-blurple-500 text-white shadow-glow hover:bg-blurple-600 hover:-translate-y-0.5",
25	  gradient:
26	    "bg-gradient-to-r from-blurple-500 to-sky-500 text-white shadow-glow hover:-translate-y-0.5",
27	  light:
28	    "bg-white text-ink shadow-soft hover:-translate-y-0.5 hover:shadow-card",
29	  outlineLight:
30	    "border border-white/30 text-white hover:border-white/55 hover:bg-white/10",
31	  outlineDark:
32	    "border border-line bg-white text-ink hover:border-ink/20 hover:bg-mist",
33	  ghost: "px-0 text-blurple-600 hover:gap-3 hover:text-blurple-500",
34	};
35	
36	type ButtonProps = {
37	  variant?: Variant;
38	  size?: Size;
39	  withArrow?: boolean;
40	  className?: string;
41	  children: React.ReactNode;
42	  href?: string;
43	  external?: boolean;
44	  type?: "button" | "submit" | "reset";
45	  onClick?: React.MouseEventHandler;
46	  disabled?: boolean;
47	  "aria-label"?: string;
48	};
49	
50	export function Button({
51	  variant = "primary",
52	  size = "md",
53	  withArrow,
54	  className,
55	  children,
56	  href,
57	  external,
58	  type,
59	  onClick,
60	  disabled,
61	  ...rest
62	}: ButtonProps) {
63	  const classes = cn(base, sizes[size], variants[variant], className);
64	  const inner = (
65	    <>
66	      {children}
67	      {withArrow && (
68	        <ArrowRight className="h-4 w-4 transition-transform duration-300 group-hover:translate-x-0.5" />
69	      )}
70	    </>
71	  );
72	
73	  if (href) {
74	    if (external) {
75	      return (
76	        <a href={href} target="_blank" rel="noreferrer" className={classes} {...rest}>
77	          {inner}
78	        </a>
79	      );
80	    }
81	    return (
82	      <Link href={href} className={classes} {...rest}>
83	        {inner}
84	      </Link>
85	    );
86	  }
87	
