@import "tailwindcss";

@theme {
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, -apple-system, sans-serif;
  --font-display: var(--font-space-grotesk), var(--font-inter), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jetbrains-mono), ui-monospace, SFMono-Regular, monospace;

  /* Stripe-inspired core */
  --color-ink: #0a2540;        /* headings — Stripe navy */
  --color-slate: #425466;      /* body text */
  --color-mist: #f6f9fc;       /* light section bg (cloud) */
  --color-cloud: #eef3f9;      /* slightly deeper light */
  --color-line: #e3e8ee;       /* borders */

  --color-blurple-300: #b7b2ff;
  --color-blurple-400: #8a83ff;
  --color-blurple-500: #635bff; /* brand primary */
  --color-blurple-600: #5249f0;
  --color-blurple-700: #4239d6;

  --color-sky-400: #00d4ff;
  --color-sky-500: #0bb5ff;
  --color-mintx-400: #3ecf8e;
  --color-mintx-500: #23c386;
  --color-coral-400: #ff7eb6;
  --color-coral-500: #ff5996;
  --color-peach-400: #ffd79d;

  /* legacy aliases kept for continuity */
  --color-navy-950: #061022;
  --color-navy-900: #0a2540;
  --color-navy-800: #102a43;
  --color-navy-700: #1c3a5e;
  --color-navy-600: #2a4a73;
  --color-electric-700: #4239d6;
  --color-electric-600: #5249f0;
  --color-electric-500: #635bff;
  --color-electric-400: #8a83ff;
  --color-electric-300: #b7b2ff;
  --color-iris: #7c5cff;
  --color-aqua: #00d4ff;

  /* Stripe-style soft layered shadows */
  --shadow-soft: 0 2px 5px -1px rgba(50, 50, 93, 0.12), 0 1px 3px -1px rgba(10, 37, 64, 0.12);
  --shadow-card: 0 13px 27px -8px rgba(50, 50, 93, 0.18), 0 8px 16px -10px rgba(10, 37, 64, 0.12);
  --shadow-lift: 0 24px 48px -14px rgba(50, 50, 93, 0.22), 0 12px 24px -16px rgba(10, 37, 64, 0.14);
  --shadow-xl: 0 50px 100px -28px rgba(50, 50, 93, 0.3), 0 30px 60px -32px rgba(10, 37, 64, 0.2);
  --shadow-glow: 0 16px 40px -12px rgba(99, 91, 255, 0.5);

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}

@layer base {
  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
  }
  body {
    background-color: #ffffff;
    color: var(--color-slate);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
    overflow-x: hidden;
  }
  h1, h2, h3, h4 {
    font-family: var(--font-display);
    color: var(--color-ink);
    letter-spacing: -0.025em;
    line-height: 1.05;
  }
  ::selection {
    background: rgba(99, 91, 255, 0.22);
    color: var(--color-ink);
  }
  :focus-visible {
    outline: 2px solid var(--color-blurple-500);
    outline-offset: 3px;
    border-radius: 4px;
  }
}

/* ---- Gradient text ---- */
.text-gradient {
  background-image: linear-gradient(100deg, #635bff 0%, #2d8dff 48%, #00d4ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.text-gradient-warm {
  background-image: linear-gradient(100deg, #635bff 0%, #ff5996 60%, #ffb15c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.text-gradient-light {
  background-image: linear-gradient(100deg, #ffffff 0%, #d7e6ff 55%, #9fd4ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* ---- Backgrounds & textures ---- */
.bg-grid-light {
  background-image:
    linear-gradient(rgba(10, 37, 64, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(10, 37, 64, 0.05) 1px, transparent 1px);
  background-size: 56px 56px;
}
.bg-grid-dark {
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.06) 1px, transparent 1px);
  background-size: 56px 56px;
}
.bg-dots {
  background-image: radial-gradient(rgba(255, 255, 255, 0.12) 1px, transparent 1px);
  background-size: 22px 22px;
}
.bg-dots-dark {
  background-image: radial-gradient(rgba(10, 37, 64, 0.08) 1px, transparent 1px);
  background-size: 22px 22px;
}
/* The signature flowing gradient banner */
.bg-flow {
  background:
    radial-gradient(40% 60% at 12% 18%, rgba(99, 91, 255, 0.65) 0%, transparent 60%),
    radial-gradient(38% 55% at 78% 14%, rgba(0, 212, 255, 0.55) 0%, transparent 60%),
    radial-gradient(45% 60% at 72% 78%, rgba(62, 207, 142, 0.45) 0%, transparent 62%),
    radial-gradient(40% 55% at 24% 82%, rgba(255, 126, 182, 0.5) 0%, transparent 60%),
    radial-gradient(60% 80% at 50% 40%, rgba(255, 215, 157, 0.28) 0%, transparent 70%),
    linear-gradient(165deg, #eef1ff 0%, #f6f9fc 100%);
}

.mask-fade-edges {
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 10%, #000 90%, transparent);
  mask-image: linear-gradient(90deg, transparent, #000 10%, #000 90%, transparent);
}
.mask-fade-b {
  -webkit-mask-image: linear-gradient(180deg, #000 55%, transparent);
  mask-image: linear-gradient(180deg, #000 55%, transparent);
}

/* ---- Angled section edges (Stripe diagonal cuts) ---- */
.clip-angle-b {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 4.5vw), 0 100%);
}
.clip-angle-t {
  clip-path: polygon(0 4.5vw, 100% 0, 100% 100%, 0 100%);
}
.clip-angle-tb {
  clip-path: polygon(0 4.5vw, 100% 0, 100% calc(100% - 4.5vw), 0 100%);
}

/* ---- Glass & gradient ring ---- */
.glass-dark {
  background: rgba(10, 37, 64, 0.55);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.12);
}
.glass-light {
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(10, 37, 64, 0.07);
}
.ring-gradient {
  position: relative;
  isolation: isolate;
}
.ring-gradient::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(130deg, rgba(99, 91, 255, 0.7), rgba(0, 212, 255, 0.4) 50%, rgba(62, 207, 142, 0.5));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

/* ---- Keyframes ---- */
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
.animate-marquee { animation: marquee 38s linear infinite; }
.animate-marquee-slow { animation: marquee 64s linear infinite; }

@keyframes floaty {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-16px); }
}
.animate-floaty { animation: floaty 9s ease-in-out infinite; }

@keyframes pulse-glow {
  0%, 100% { opacity: 0.55; transform: scale(1); }
  50% { opacity: 0.85; transform: scale(1.08); }
}
.animate-pulse-glow { animation: pulse-glow 9s ease-in-out infinite; }

@keyframes drift {
  0%, 100% { transform: translate(0, 0) scale(1); }
  33% { transform: translate(6%, -5%) scale(1.08); }
  66% { transform: translate(-5%, 4%) scale(0.96); }
}
.animate-drift { animation: drift 18s ease-in-out infinite; }
.animate-drift-2 { animation: drift 22s ease-in-out infinite reverse; }

@keyframes spin-slow {
  to { transform: rotate(360deg); }
}
.animate-spin-slow { animation: spin-slow 26s linear infinite; }

/* ---- Scrollbar ---- */
::-webkit-scrollbar { width: 11px; height: 11px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(66, 84, 102, 0.32);
  border-radius: 999px;
  border: 3px solid transparent;
  background-clip: padding-box;
}
::-webkit-scrollbar-thumb:hover { background: rgba(66, 84, 102, 0.5); background-clip: padding-box; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
  .animate-marquee, .animate-marquee-slow, .animate-floaty, .animate-pulse-glow,
  .animate-spin-slow, .animate-drift, .animate-drift-2 {
    animation: none !important;
  }
}

"use client";

import { motion, useReducedMotion, type Variants } from "framer-motion";
import {
  ArrowUpRight,
  Check,
  LayoutGrid,
  BarChart3,
  FolderKanban,
  Users,
  Settings,
  TrendingUp,
} from "lucide-react";
import { Container } from "@/components/ui/Container";
import { Button } from "@/components/ui/Button";
import { BrowserFrame } from "@/components/ui/BrowserFrame";
import { site } from "@/lib/site";

const EASE = [0.16, 1, 0.3, 1] as const;
const bars = [44, 60, 52, 72, 58, 86, 68, 80];
const metrics = [
  { label: "Revenue", value: "$1.2M", delta: "+12.4%" },
  { label: "Active users", value: "48.2k", delta: "+8.1%" },
  { label: "Conversion", value: "4.9%", delta: "+2.3%" },
];
const navIcons = [LayoutGrid, BarChart3, FolderKanban, Users, Settings];

export function Hero() {
  const reduce = useReducedMotion();

  const container: Variants = {
    hidden: {},
    show: { transition: { staggerChildren: 0.08, delayChildren: 0.04 } },
  };
  const item: Variants = {
    hidden: { opacity: 0, y: 22 },
    show: { opacity: 1, y: 0, transition: { duration: 0.65, ease: EASE } },
  };
  const motionProps = reduce
    ? {}
    : { variants: container, initial: "hidden" as const, animate: "show" as const };
  const child = reduce ? {} : { variants: item };

  return (
    <section className="relative isolate overflow-hidden">
      {/* Flowing gradient banner with angled bottom */}
      <div className="clip-angle-b absolute inset-0 -z-10 bg-flow" aria-hidden>
        <div className="absolute -left-20 top-10 h-96 w-96 animate-drift rounded-full bg-blurple-500/30 blur-[120px]" />
        <div className="absolute right-0 top-0 h-96 w-96 animate-drift-2 rounded-full bg-sky-400/30 blur-[120px]" />
        <div className="absolute bottom-10 left-1/3 h-80 w-80 animate-drift rounded-full bg-coral-400/25 blur-[120px]" />
        <div className="absolute inset-0 bg-grid-light opacity-40" />
      </div>

      <Container className="relative pb-28 pt-32 md:pb-36 md:pt-40">
        <motion.div className="mx-auto max-w-3xl text-center" {...motionProps}>
          <motion.div {...child}>
            <span className="inline-flex items-center gap-2.5 rounded-full border border-ink/10 bg-white/70 px-4 py-1.5 font-mono text-[11px] uppercase tracking-[0.16em] text-ink/70 shadow-soft backdrop-blur">
              <span className="relative flex h-1.5 w-1.5">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-blurple-500 opacity-75" />
                <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-blurple-500" />
              </span>
              The technology partner for ambitious teams
            </span>
          </motion.div>

          <motion.h1
            {...child}
            className="mt-7 text-balance text-[2.75rem] font-semibold leading-[1.02] tracking-tight text-ink sm:text-6xl lg:text-[4.5rem]"
          >
            Ignite innovation.
            <br />
            Empower <span className="text-gradient">growth.</span>
          </motion.h1>

          <motion.p
            {...child}
            className="mx-auto mt-6 max-w-xl text-lg leading-relaxed text-slate"
          >
            Spark is the end-to-end technology partner for startups, SMEs, and
            enterprises — we design, build, and scale the software that powers
            your business.
          </motion.p>

          <motion.div
            {...child}
            className="mt-9 flex flex-wrap items-center justify-center gap-3"
          >
            <Button href="/contact" variant="gradient" size="lg" withArrow>
              Start your project
            </Button>
            <Button href="/services" variant="outlineDark" size="lg">
              Explore services
            </Button>
          </motion.div>

          <motion.div
            {...child}
            className="mt-10 flex flex-wrap items-center justify-center gap-x-8 gap-y-3 font-mono text-sm text-slate"
          >
            <span>
              <span className="font-semibold text-ink">{site.stats.clients}</span>{" "}
              clients
            </span>
            <span className="hidden h-4 w-px bg-ink/15 sm:block" />
            <span>
              <span className="font-semibold text-ink">{site.stats.projects}</span>{" "}
              projects
            </span>
            <span className="hidden h-4 w-px bg-ink/15 sm:block" />
            <span>
              <span className="font-semibold text-ink">{site.stats.regions}</span>{" "}
              regions
            </span>
          </motion.div>
        </motion.div>

        {/* Product showcase */}
        <motion.div
          initial={reduce ? false : { opacity: 0, y: 36, scale: 0.97 }}
          animate={reduce ? undefined : { opacity: 1, y: 0, scale: 1 }}
          transition={{ duration: 0.9, delay: 0.3, ease: EASE }}
          className="relative mx-auto mt-16 max-w-5xl"
        >
          {/* floating chips */}
          <div className="animate-floaty absolute -left-4 top-16 z-10 hidden rounded-xl border border-line bg-white px-3.5 py-2.5 shadow-lift md:block">
            <div className="flex items-center gap-2.5">
              <span className="inline-flex h-7 w-7 items-center justify-center rounded-full bg-mintx-400/15 text-mintx-500">
                <Check className="h-4 w-4" />
              </span>
              <div>
                <p className="text-xs font-semibold text-ink">Deployed</p>
                <p className="font-mono text-[10px] text-slate">production · 2.1s</p>
              </div>
            </div>
          </div>
          <div className="animate-floaty absolute -right-4 bottom-16 z-10 hidden rounded-xl border border-line bg-white px-3.5 py-2.5 shadow-lift [animation-delay:1.5s] md:block">
            <div className="flex items-center gap-2.5">
              <span className="inline-flex h-7 w-7 items-center justify-center rounded-full bg-blurple-500/10 text-blurple-600">
                <TrendingUp className="h-4 w-4" />
              </span>
              <div>
                <p className="text-xs font-semibold text-ink">+63% revenue</p>
                <p className="font-mono text-[10px] text-mintx-500">▲ this quarter</p>
              </div>
            </div>
          </div>

          <BrowserFrame url="app.spark.dev/overview">
            <div className="grid grid-cols-1 sm:grid-cols-[190px_1fr]">
              {/* sidebar */}
              <div className="hidden flex-col gap-1 border-r border-line bg-mist/60 p-4 sm:flex">
                <div className="mb-4 flex items-center gap-2 px-2">
                  <span className="h-6 w-6 rounded-md bg-gradient-to-br from-blurple-500 to-sky-500" />
                  <span className="font-display text-sm font-semibold text-ink">
                    Spark
                  </span>
                </div>
                {["Dashboard", "Analytics", "Projects", "Team", "Settings"].map(
                  (label, i) => {
                    const Icon = navIcons[i];
                    return (
                      <div
                        key={label}
                        className={`flex items-center gap-2.5 rounded-lg px-3 py-2 text-sm ${
                          i === 0
                            ? "bg-white font-medium text-ink shadow-soft"
                            : "text-slate"
                        }`}
                      >
                        <Icon className="h-4 w-4" />
                        {label}
                      </div>
                    );
                  },
                )}
              </div>

              {/* main */}
              <div className="p-5 sm:p-6">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="font-display text-lg font-semibold text-ink">
                      Overview
                    </p>
                    <p className="text-xs text-slate">Last 30 days</p>
                  </div>
                  <span className="rounded-full bg-blurple-500/10 px-3 py-1 text-xs font-medium text-blurple-600">
                    Live
                  </span>
                </div>

                <div className="mt-5 grid grid-cols-3 gap-3">
                  {metrics.map((m) => (
                    <div key={m.label} className="rounded-xl border border-line bg-white p-3">
                      <p className="truncate text-[11px] text-slate">{m.label}</p>
                      <p className="mt-1 font-display text-base font-semibold text-ink sm:text-xl">
                        {m.value}
                      </p>
                      <p className="mt-0.5 inline-flex items-center gap-0.5 text-[11px] font-medium text-mintx-500">
                        <ArrowUpRight className="h-3 w-3" />
                        {m.delta}
                      </p>
                    </div>
                  ))}
                </div>

                <div className="mt-4 rounded-xl border border-line bg-white p-4">
                  <div className="flex items-end justify-between">
                    <p className="text-xs font-medium text-slate">Revenue</p>
                    <p className="font-mono text-[11px] text-slate">2025</p>
                  </div>
                  <div className="mt-4 flex h-28 items-end gap-2">
                    {bars.map((h, i) => (
                      <div
                        key={i}
                        style={{ height: `${h}%` }}
                        className={`flex-1 rounded-t ${
                          i === bars.length - 3
                            ? "bg-gradient-to-t from-blurple-500 to-sky-400"
                            : "bg-blurple-500/15"
                        }`}
                      />
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </BrowserFrame>
        </motion.div>
      </Container>
    </section>
  );
}

