import Link from "next/link";
import { Sparkles } from "lucide-react";
import { Container } from "@/components/ui/Container";
import { Button } from "@/components/ui/Button";
import { Reveal } from "@/components/ui/Reveal";
import { iconMap } from "@/lib/icons";
import { aiCategories, aiStats } from "@/lib/data/aiServices";
import { cn } from "@/lib/utils";

export function AIServices() {
  return (
    <section
      id="ai"
      className="clip-angle-tb relative isolate overflow-hidden bg-navy-950 text-white"
    >
      {/* Atmospheric background */}
      <div className="pointer-events-none absolute inset-0" aria-hidden>
        <div className="absolute inset-0 bg-grid-dark opacity-60" />
        <div className="absolute -left-24 top-16 h-96 w-96 animate-drift rounded-full bg-blurple-500/30 blur-[130px]" />
        <div className="absolute right-0 top-1/3 h-96 w-96 animate-drift-2 rounded-full bg-sky-400/25 blur-[130px]" />
        <div className="absolute bottom-0 left-1/3 h-80 w-80 animate-drift rounded-full bg-mintx-400/20 blur-[130px]" />
      </div>

      <Container className="relative py-28 md:py-36">
        {/* Header */}
        <div className="mx-auto max-w-3xl text-center">
          <span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/5 px-4 py-1.5 font-mono text-[11px] uppercase tracking-[0.2em] text-white/75 backdrop-blur">
            <Sparkles className="h-3.5 w-3.5 text-sky-400" />
            Artificial Intelligence
          </span>
          <h2 className="mt-6 text-balance font-display text-[2rem] font-semibold leading-[1.06] sm:text-4xl md:text-[2.9rem]">
            Put <span className="text-gradient-light">AI</span> at the core of how
            you operate
          </h2>
          <p className="mx-auto mt-5 max-w-2xl text-lg leading-relaxed text-white/65">
            From strategy to autonomous agents, we help you design, build, and
            scale AI that ships real outcomes — not demos.
          </p>
          <div className="mt-9 flex flex-wrap items-center justify-center gap-3">
            <Button href="/ai" variant="gradient" size="lg" withArrow>
              Explore AI services
            </Button>
            <Button href="/contact?intent=ai" variant="outlineLight" size="lg">
              Talk to an AI expert
            </Button>
