                {s.value}
              </p>
              <p className="mt-1 text-sm leading-snug text-slate">{s.label}</p>
            </div>
          ))}
        </div>
      </PageHero>

      {aiCategories.map((cat, idx) => {
        const CatIcon = iconMap[cat.icon];
        return (
          <Section key={cat.slug} id={cat.slug} tone={idx % 2 === 0 ? "light" : "mist"}>
