"use client";

import { useState } from "react";
import { ArrowRight, Check } from "lucide-react";

export function NewsletterForm() {
  const [email, setEmail] = useState("");
  const [done, setDone] = useState(false);

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        if (!email) return;
        setDone(true);
        setEmail("");
        window.setTimeout(() => setDone(false), 3500);
      }}
      className="mt-4"
    >
      <div className="flex items-center gap-2 rounded-full border border-white/15 bg-white/5 p-1.5 pl-4 transition-colors focus-within:border-white/35">
        <input
          type="email"
          required
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="you@company.com"
          aria-label="Email address"
          className="w-full bg-transparent text-sm text-white placeholder:text-white/40 focus:outline-none"
        />
        <button
          type="submit"
          aria-label="Subscribe"
          className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-electric-500 text-white transition-all hover:bg-electric-400"
        >
          {done ? <Check className="h-4 w-4" /> : <ArrowRight className="h-4 w-4" />}
        </button>
      </div>
      <p className="mt-2.5 h-4 text-xs text-white/45">
        {done ? "Thanks — you're on the list." : "Monthly insights. No spam, unsubscribe anytime."}
      </p>
    </form>
  );
}

import Link from "next/link";
import { ArrowUpRight } from "lucide-react";
import type { CaseStudy } from "@/lib/data/caseStudies";
import { cn } from "@/lib/utils";

export function CaseStudyCard({
  study,
  variant = "light",
}: {
  study: CaseStudy;
  variant?: "light" | "dark";
}) {
  const dark = variant === "dark";
  return (
    <Link
      href={`/work/${study.slug}`}
      className={cn(
        "group flex h-full flex-col overflow-hidden rounded-2xl border transition-all duration-300 hover:-translate-y-1.5",
        dark
          ? "border-white/10 bg-navy-800/50 hover:border-white/20"
          : "border-line bg-white hover:shadow-lift",
      )}
    >
      <div className={cn("relative h-44 overflow-hidden bg-gradient-to-br", study.accent)}>
        <div className="absolute inset-0 bg-dots opacity-40" aria-hidden />
        <div
          className="absolute inset-0 bg-gradient-to-t from-black/35 to-transparent"
          aria-hidden
        />
        <span className="absolute bottom-4 left-5 font-display text-3xl font-bold tracking-tight text-white/95">
          {study.client}
        </span>
        <span className="absolute right-4 top-4 rounded-full bg-white/20 px-2.5 py-1 font-mono text-[10px] uppercase tracking-wider text-white backdrop-blur">
          {study.results[0].value} {study.results[0].label}
        </span>
      </div>
      <div className="flex flex-1 flex-col p-6">
        <div
          className={cn(
            "flex items-center gap-2 font-mono text-[11px] uppercase tracking-[0.14em]",
            dark ? "text-white/45" : "text-slate-400",
          )}
        >
          <span>{study.industry}</span>
          <span aria-hidden>·</span>
          <span>{study.year}</span>
        </div>
        <h3
          className={cn(
            "mt-3 font-display text-lg font-semibold leading-snug",
            dark ? "text-white" : "text-ink",
          )}
        >
          {study.title}
        </h3>
        <p
          className={cn(
            "mt-2 flex-1 text-sm leading-relaxed",
            dark ? "text-white/55" : "text-slate-500",
          )}
        >
          {study.summary}
        </p>
        <span
          className={cn(
            "mt-5 inline-flex items-center gap-1.5 text-sm font-medium",
            dark ? "text-electric-300" : "text-electric-600",
          )}
        >
          Read case study
          <ArrowUpRight className="h-4 w-4 transition-transform duration-300 group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
        </span>
      </div>
    </Link>
  );
}

