// Illustrative case studies — fictional clients and metrics for layout purposes.
// Replace with real, approved client stories before launch.

export type CaseResult = { value: string; label: string };

export type CaseStudy = {
  slug: string;
  client: string;
  title: string;
  industry: string;
  year: string;
  services: string[];
  tech: string[];
  summary: string;
  challenge: string;
  approach: string[];
  solution: string;
  results: CaseResult[];
  quote: { text: string; author: string; role: string };
  accent: string;
};

export const caseStudies: CaseStudy[] = [
  {
    slug: "northbound-shopify-replatform",
    client: "Northbound",
    title: "Replatforming a retailer for 2× revenue growth",
    industry: "Retail & eCommerce",
    year: "2025",
    services: ["Digital Transformation", "UI & UX Design", "Support & Maintenance"],
    tech: ["Shopify", "React", "Node.js", "TypeScript"],
    summary:
      "A heritage outdoor retailer was losing customers to a slow, dated storefront. We replatformed onto a modern headless stack and redesigned the buying experience end to end.",
    challenge:
      "Northbound's legacy storefront took over six seconds to load, broke on mobile, and made even simple merchandising changes a developer ticket. Conversion was sliding and the team was flying blind on data.",
    approach: [
      "Audited the existing stack, analytics, and customer journey to find the real friction.",
      "Designed a fast, mobile-first storefront with a flexible merchandising system.",
      "Replatformed onto headless Shopify with a React front end and clean integrations.",
      "Instrumented analytics and handed over a system the marketing team could run themselves.",
    ],
    solution:
      "A headless commerce platform with sub-1.5s loads, a design system the team controls without engineering, and a data layer that finally tells them what's working.",
    results: [
      { value: "+63%", label: "conversion rate" },
      { value: "-45%", label: "page load time" },
      { value: "2.1×", label: "online revenue" },
    ],
    quote: {
      text: "They replatformed our entire store in weeks, and our conversion rate has never been higher.",
      author: "Elena Marsh",
      role: "VP eCommerce, Northbound",
    },
    accent: "from-electric-500 to-iris",
  },
  {
    slug: "cargoflow-driver-app",
    client: "Cargoflow",
    title: "A logistics app that scaled to 40,000 drivers",
    industry: "Logistics & Supply Chain",
    year: "2024",
    services: ["Mobile App Development", "UI & UX Design"],
    tech: ["React Native", "Node.js", "PostgreSQL", "AWS"],
    summary:
      "Cargoflow needed to move their driver network off paper and phone calls. We built an offline-first mobile app that became the backbone of their operation.",
    challenge:
      "Dispatch ran on spreadsheets and phone calls. Drivers in low-connectivity areas had no reliable way to receive jobs, capture proof of delivery, or report issues — and delays were piling up.",
    approach: [
      "Shadowed drivers and dispatchers to design around real field conditions.",
      "Built an offline-first React Native app with background sync and live tracking.",
      "Engineered a scalable backend to handle tens of thousands of concurrent drivers.",
      "Rolled out region by region with in-app onboarding and support.",
    ],
    solution:
      "A single app for jobs, navigation, proof of delivery, and support — that works even with no signal and syncs the moment connectivity returns.",
    results: [
      { value: "40k+", label: "active drivers" },
      { value: "-28%", label: "delivery delays" },
      { value: "4.8★", label: "app store rating" },
    ],
    quote: {
      text: "The app scaled to 40,000 drivers without a hitch. Rare to find a partner this senior and this fast.",
      author: "Daniel Okoro",
      role: "CTO, Cargoflow",
    },
    accent: "from-electric-400 to-aqua",
  },
  {
    slug: "meridian-pay-transformation",
    client: "Meridian Pay",
    title: "Digital transformation that cut costs by half",
    industry: "Financial Services",
    year: "2025",
    services: ["Digital Transformation", "Support & Maintenance"],
    tech: ["Java", "Kubernetes", "Azure", "PostgreSQL"],
    summary:
      "A growing payments company was buckling under manual operations and brittle infrastructure. We modernised the platform and automated the work behind the scenes.",
    challenge:
      "Meridian's core systems were a tangle of manual processes and aging servers. Outages were frequent, scaling meant hiring, and compliance reporting ate entire weeks each month.",
    approach: [
      "Mapped the operating model to find the highest-leverage automation opportunities.",
      "Migrated core systems to a resilient, containerised cloud platform.",
      "Automated reconciliation, reporting, and compliance workflows.",
      "Set up 24/7 monitoring and an SLA-backed support model.",
    ],
    solution:
      "A cloud-native platform with automated operations and near-perfect uptime — so the team scales with volume, not headcount.",
    results: [
      { value: "-52%", label: "operating cost" },
      { value: "99.99%", label: "platform uptime" },
      { value: "6 wks", label: "to first release" },
    ],
    quote: {
      text: "Our digital transformation actually transformed something. Costs down, uptime up, team happier.",
      author: "Priya Nair",
      role: "COO, Meridian Pay",
    },
    accent: "from-iris to-electric-500",
  },
];

export function getCaseStudy(slug: string): CaseStudy | undefined {
  return caseStudies.find((c) => c.slug === slug);
}

