import { Container } from "@/components/ui/Container";
import { Marquee } from "@/components/ui/Marquee";
import { clients } from "@/lib/data/clients";

export function TrustBar() {
  return (
    <section className="border-b border-line bg-white py-12">
      <Container>
        <p className="text-center font-mono text-xs uppercase tracking-[0.2em] text-slate-400">
          Trusted by ambitious teams across 5 regions
        </p>
      </Container>
      <div className="mt-8">
        <Marquee>
          {clients.map((c) => (
            <span
              key={c}
              className="mx-8 whitespace-nowrap font-display text-xl font-semibold text-ink/25 transition-colors duration-300 hover:text-ink/60"
