import type { Service } from "@/lib/data/services";
import { cn } from "@/lib/utils";

export function ServiceCard({
  service,
  index,
}: {
  service: Service;
  index?: number;
}) {
  const Icon = iconMap[service.icon];
  return (
    <Link
      href={`/services/${service.slug}`}
      className="group relative flex h-full flex-col overflow-hidden rounded-2xl border border-line bg-white p-7 transition-all duration-300 hover:-translate-y-1 hover:border-transparent hover:shadow-lift"
    >
      {/* Soft accent glow */}
